Database Schema:
CREATE TABLE `genre` (
  `id` INTEGER,
  `genre_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `game` (
  `id` INTEGER,
  `genre_id` INTEGER REFERENCES `genre`(`id`),
  `game_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `platform` (
  `id` INTEGER,
  `platform_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `publisher` (
  `id` INTEGER,
  `publisher_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `game_publisher` (
  `id` INTEGER,
  `game_id` INTEGER REFERENCES `game`(`id`),
  `publisher_id` INTEGER REFERENCES `publisher`(`id`),
  PRIMARY KEY (`id`)
);

CREATE TABLE `game_platform` (
  `id` INTEGER,
  `game_publisher_id` INTEGER REFERENCES `game_publisher`(`id`),
  `platform_id` INTEGER REFERENCES `platform`(`id`),
  `release_year` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `region` (
  `id` INTEGER,
  `region_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `region_sales` (
  `region_id` INTEGER REFERENCES `region`(`id`),
  `game_platform_id` INTEGER REFERENCES `game_platform`(`id`),
  `num_sales` REAL
);

Question:
What genre is the game 2010 FIFA World Cup South Africa?

Evidence:
genre refers to genre_name; 2010 FIFA World Cup South Africa refers to game_name = '2010 FIFA World Cup South Africa';

Database Schema:
CREATE TABLE `Ref_Document_Types` (
