Database Schema:
CREATE TABLE `atom` (
  `atom_id` TEXT,
  `molecule_id` TEXT REFERENCES `molecule`(`molecule_id`),
  `element` TEXT,
  PRIMARY KEY (`atom_id`)
);

CREATE TABLE `bond` (
  `bond_id` TEXT,
  `molecule_id` TEXT REFERENCES `molecule`(`molecule_id`),
  `bond_type` TEXT,
  PRIMARY KEY (`bond_id`)
);

CREATE TABLE `connected` (
  `atom_id` TEXT REFERENCES `atom`(`atom_id`),
  `atom_id2` TEXT REFERENCES `atom`(`atom_id`),
  `bond_id` TEXT REFERENCES `bond`(`bond_id`),
  PRIMARY KEY (`atom_id`, `atom_id2`)
);

CREATE TABLE `molecule` (
  `molecule_id` TEXT,
  `label` TEXT,
  PRIMARY KEY (`molecule_id`)
);

Question:
How many molecules have a double bond type and among these molecule, how many are labeled as carcinogenic compound?

Evidence:
double bond refers to bond_type = ' = '; label = '+' mean molecules are carcinogenic;

